properties.expression:
effobj = thisProperty.propertyGroup(1);
vector = effobj.param(6);
p1 =  effobj.param(3);
p2 =  effobj.param(4);
p3 =  effobj.param(5);
maxBendDist = length(p1, p2);
v = (p2 - p1) / maxBendDist;
a = -degreesToRadians(effobj.param(8));
toBend = (p3 - p1);
projV = dot(toBend, v);
res = [0,0];
if (projV < 0 || a == 0) {
    res = p3;
} else {
    n = [v[1], -v[0]];
    projN = dot(toBend, n);
    k = maxBendDist / a;
    r = k - projN;
    straight = [0, 0];
    d = projV - maxBendDist;
    if (d > 0) {
        projV = maxBendDist;
        b2 = Math.PI - a;
        straight = Math.cos(b2) * n + Math.sin(b2) * v;
        straight = d * [straight[1], -straight[0]];
    }
    prop = projV / k;
    bent = (r - r * Math.cos(prop)) * n + (r * Math.sin(prop)) * v;
    root = p1 + projN * n;
    res = root + bent + straight;
}

if (vector == 1) {
    parent.fromComp(res);
}else{
    res;
}

effobj = thisProperty.propertyGroup(1);
