transform.expression:
margin = 80;
mySize = thisLayer.sourceRectAtTime();
halfWidth  = mySize.width * 0.5;
halfHeight = mySize.height * 0.5;

pMin = [0,0] + [halfWidth,halfHeight] + [margin,margin];
pMax = [width,height] - [halfWidth,halfHeight] - [margin,margin];

hold = framesToTime(effect("Frames - Duration")("Slider"));
seed = effect("Seed")("Slider");
zeroWiggle = thisProperty.valueAtTime(0) - wiggle(1,15);
seedRandom(Math.floor((time + seed) / hold), true);

// === GET EXCLUSION ZONE ("MINUS" layer) ===
try{
	minusLayer = thisComp.layer("MINUS");
minusRect = minusLayer.sourceRectAtTime(time);
