var amp = .18;        // Height of the wave
var freq = 12;         // Base speed
var roughness = 1;   // How "irregular" it is

// The Math
// We use noise() to create a smooth but unpredictable offset for the time
var irregularOffset = Math.abs(noise(time * 0.5)) * roughness;

// Combine standard time with our irregular offset
var val = Math.sin((5 + time + irregularOffset) * freq) * amp;

// Output (for a single-value property)
value + val

